def print_banner(console: Console | None = None) -> None:
    """Print the full-fidelity Nullify ASCII art banner."""
    c = console or Console()
    try:
        for line in BANNER_ANSI_LINES:
            c.print(Text.from_ansi(line))
    except Exception:  # noqa: BLE001
        c.print(f"[bold cyan]{FALLBACK_ASCII}[/bold cyan]")
